using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace BeamScheduleFormatter {
sealed class ExcelStaWorker:IDisposable {
 readonly Thread thread;readonly ManualResetEventSlim ready=new ManualResetEventSlim();Control dispatcher;Exception startup;bool disposed;
 public ExcelStaWorker(){thread=new Thread(()=>{try{ExcelBusyFilter.Register();dispatcher=new Control();dispatcher.CreateControl();var handle=dispatcher.Handle;ready.Set();Application.Run();dispatcher.Dispose();}catch(Exception e){startup=e;ready.Set();}}){IsBackground=true,Name="DTCE Excel STA"};thread.SetApartmentState(ApartmentState.STA);thread.Start();if(!ready.Wait(10000))throw new Exception("Excel worker could not start.");if(startup!=null)throw startup;}
 public Task<T> Run<T>(Func<T> work){var task=new TaskCompletionSource<T>();if(disposed){task.SetException(new ObjectDisposedException("Excel worker"));return task.Task;}try{dispatcher.BeginInvoke((Action)(()=>{try{task.SetResult(ExcelBusyFilter.Retry(work));}catch(Exception e){task.SetException(e);}}));}catch(Exception e){task.SetException(e);}return task.Task;}
 public Task Run(Action work){return Run(()=>{work();return true;});}
 public void Dispose(){if(disposed)return;disposed=true;try{dispatcher.BeginInvoke((Action)(()=>Application.ExitThread()));}catch{}ready.Dispose();}
}
class BackupWritePlan {public List<BackupDemand> Demands;public List<BackupTarget> Targets;public Dictionary<string,BackupTarget> Routes;public int Unmapped{get{return Demands.Count(d=>!Routes.ContainsKey(d.Key));}}}
sealed partial class ExcelLiveLink {
 List<BackupTarget> targetCache;Dictionary<string,BackupTarget> routeCache;Dictionary<string,string> nameIdentityCache;bool detailsHidden;
 /* Owner (19 November 2026, "hindi isasave ng app, manual save ang excel"): the Program of Works writes its quantities into the open
    workbook but never saves the file; the owner saves it in Excel. Earlier builds saved it 5 seconds after the last change. */
 public bool HasUnsavedChanges{get{try{return book!=null&&!Convert.ToBoolean(book.Saved);}catch(Exception){return false;}}}
 public BackupWritePlan PrepareQuantityWrite(List<BackupDemand> input,bool refresh=false){var targets=refresh||targetCache==null?RegisterBackupBillItems():targetCache;var demands=input.Where(d=>d.ManualOverride||d.Quantity>1e-10||d.Sources.Any(s=>s.Quantity>1e-10)||LastBackupRoutes!=null&&LastBackupRoutes.ContainsKey(d.Key)).ToList();Dictionary<string,BackupTarget> routes;if(refresh||routeCache==null){routes=BackupRoutes(demands,targets);routeCache=new Dictionary<string,BackupTarget>(routes);}else{routes=new Dictionary<string,BackupTarget>();foreach(var d in demands){BackupTarget t;if(d.TargetSlotId!=null)t=BackupMapping.ResolveTarget(d,targets);else if(!routeCache.TryGetValue(d.Key,out t))t=BackupMapping.Suggest(d,targets);if(t!=null)routes[d.Key]=t;}}return new BackupWritePlan{Demands=demands,Targets=targets,Routes=routes};}
 public void ApplyQuantityWrite(BackupWritePlan plan){var mapped=plan.Demands.Where(d=>plan.Routes.ContainsKey(d.Key)).ToList();try{WriteMappedBackup(mapped,plan.Targets,plan.Routes);}catch(BackupRowsChanged){var newPlan=PrepareQuantityWrite(plan.Demands,true);if(newPlan.Unmapped>0)throw new Exception("BACKUP rows changed and mappings require review. No replacement quantities were written.");WriteMappedBackup(newPlan.Demands,newPlan.Targets,newPlan.Routes);plan.Targets=newPlan.Targets;plan.Routes=newPlan.Routes;}routeCache=new Dictionary<string,BackupTarget>(plan.Routes);}
 void VerifyQuantityTargets(List<BackupTarget> targets,IEnumerable<int> rows){foreach(int row in rows){var t=targets.Single(x=>x.Row==row);dynamic named=null;string anchor=BackupMapping.ItemPrefix+t.SlotId;if(registeredItemSlots!=null&&!registeredItemSlots.Contains(t.SlotId)){dynamic candidate=FindEstimateSheet("BACKUP");object[,] caption=(object[,])candidate.Range["B"+row+":BK"+row].Value2;int rr=caption.GetLowerBound(0),cc=caption.GetLowerBound(1);var observedNew=new BackupTarget{Code=Convert.ToString(caption[rr,cc]).Trim(),Description=Convert.ToString(caption[rr,cc+6]).Trim()};observedNew.Unit=BackupMapping.EffectiveUnit(observedNew.Code,observedNew.Description,Convert.ToString(caption[rr,cc+61]).Trim());if(BackupMapping.Identity(observedNew)!=BackupMapping.Identity(t))throw new BackupRowsChanged();SetBackupName(anchor,row,BackupMapping.Identity(t));registeredItemSlots.Add(t.SlotId);}try{named=book.Names.Item(anchor);}catch{}if(named==null){if(targetCache!=null)throw new Exception("BACKUP item anchor was removed. Refresh BACKUP items before writing.");continue;}dynamic range=named.RefersToRange;if(Convert.ToString(range.Worksheet.Name)!="BACKUP"||Convert.ToInt32(range.Column)!=55)throw new Exception("BACKUP item reference moved outside its quantity column.");int actual=Convert.ToInt32(range.Row);dynamic sheet=range.Worksheet;object[,] values=(object[,])sheet.Range["B"+actual+":BK"+actual].Value2;int r=values.GetLowerBound(0),c=values.GetLowerBound(1);var observed=new BackupTarget{Code=Convert.ToString(values[r,c]).Trim(),Description=Convert.ToString(values[r,c+6]).Trim()};observed.Unit=BackupMapping.EffectiveUnit(observed.Code,observed.Description,Convert.ToString(values[r,c+61]).Trim());if(BackupMapping.Identity(observed)!=BackupMapping.Identity(t))throw new Exception("BACKUP pay-item specification changed. Refresh and review the item before syncing.");if(actual!=row)throw new BackupRowsChanged();}}
}
class BackupRowsChanged:Exception {}
partial class ProgramOfWorksForm {
 ExcelStaWorker excelWorker;bool linkedHasBackup,linkingExcel,disconnectingExcel,excelBroken,syncPending,closingExcel,excelCloseFlushed;long quantityRevision;Task currentSync;readonly System.Windows.Forms.Timer excelSaveTimer=new System.Windows.Forms.Timer{Interval=5000};
 void SetupExcelBackground(){excelSaveTimer.Tick+=async(s,e)=>{excelSaveTimer.Stop();try{await FlushExcelFile();}catch(Exception ex){ExcelFailure(ex);}};}
 bool capturingExcelSource;
 async void LinkWorksExcel(){if(openingPow||capturingExcelSource||linkingExcel||disconnectingExcel)return;try{Guard();Commit();if(worksExcel!=null&&!excelBroken)throw new Exception("Disconnect the current workbook before linking another.");using(var d=new OpenFileDialog{Filter="Excel workbook|*.xlsm;*.xlsx",Title="Link existing quantities workbook"})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;capturingExcelSource=true;excelStatus.Text="Preparing original workbook copy in the background…";string warning=await PowWorkbookLink.Start(async()=>{var source=await Task.Run(()=>PowSourceFiles.ReadFile(path,"Excel workbook (imported original)"));if(!IsDisposed){await WaitForDeferredSources();projectSourceFiles.AddWorkbookCopy(source);}},()=>IsDisposed?Task.FromResult(true):ConnectExcel(path,false));if(!IsDisposed&&warning!="")MessageBox.Show(this,"Excel is linked. The original workbook was not embedded in the POW.\n\n"+warning+"\n\nKeep the workbook separately. Excel linking and quantity sync can continue.","Workbook attachment",MessageBoxButtons.OK,MessageBoxIcon.Information);}}catch(Exception ex){if(!IsDisposed)ExcelFailure(ex);}finally{capturingExcelSource=false;}}
 async void LinkActiveWorksExcel(){if(openingPow||capturingExcelSource)return;try{Guard();Commit();await ConnectExcel(null,true);}catch(Exception ex){ExcelFailure(ex);}}
 async Task ConnectExcel(string path,bool active){if(disconnectingExcel)throw new Exception("Excel is finishing disconnection; wait for the disconnected status.");if(linkingExcel)throw new Exception("Excel connection is already starting.");if(excelBroken)await DropExcel();if(worksExcel!=null)throw new Exception("Disconnect the current workbook before linking another.");linkingExcel=true;excelWorker=new ExcelStaWorker();var worker=excelWorker;ExcelLiveLink link=null;Exception connectionFailure=null;excelStatus.Text="Linking Excel in the background; you can continue editing.";try{link=await worker.Run(()=>active?ExcelLiveLink.AttachActiveWorkbook():new ExcelLiveLink(path,true,false));bool has=await worker.Run(()=>link.HasBackup);if(IsDisposed){await worker.Run(()=>link.Dispose());worker.Dispose();return;}worksExcel=link;linkedHasBackup=has;excelBroken=false;UpdateExcelConnectionSummary();lastExcelXml="";if(has)await LoadCatalogue();excelStatus.Text=has?"BACKUP linked. Ready to sync quantities.":"Excel linked. Ready to sync quantities.";linkingExcel=false;try{await SyncExcelAsync();}catch(Exception ex){ExcelFailure(ex);}}catch(Exception ex){connectionFailure=ex;}finally{linkingExcel=false;}if(connectionFailure!=null){if(link!=null)try{await worker.Run(()=>link.Dispose());}catch{}worker.Dispose();worksExcel=null;excelWorker=null;UpdateExcelConnectionSummary();System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(connectionFailure).Throw();}}
 async Task LoadCatalogue(){var link=worksExcel;if(link==null||!linkedHasBackup)return;var targets=await excelWorker.Run(()=>link.RegisterBackupBillItems());if(IsDisposed)return;var savedMapping=CaptureSavedBoqMapping();var lostManuals=new List<BackupBillItem>();backupBill=BackupBill.Capture(targets,RebindCatalogueManuals(targets,backupBill,lostManuals));if(childWorksDirty)Recalculate();var demands=BackupQuantities(false);var routes=await excelWorker.Run(()=>link.BackupRoutes(demands,targets));backupBillRoutes.Clear();foreach(var pair in routes)backupBillRoutes[pair.Key]=pair.Value.SlotId;/* the mapping saved in the app wins over the workbook (owner, 19 November 2026) */var lostRoutes=RestoreSavedBoqMapping(savedMapping);if((lostRoutes.Count>0||lostManuals.Count>0)&&!IsDisposed)MessageBox.Show(this,"The Bill of Quantities mapping is kept."+(lostRoutes.Count>0?" "+lostRoutes.Count+" saved mapping(s) point to BACKUP items (item no., description and unit) that are not found once in this workbook, so they are listed as Not mapped until you map them again:\n\n"+string.Join("\n",lostRoutes.Take(12).Select(k=>"- "+k.Replace("|"," | ")))+(lostRoutes.Count>12?"\n...":""):"")+(lostManuals.Count>0?"\n\nTyped quantities of "+lostManuals.Count+" item(s) are not in this workbook; type them again on the matching item:\n\n"+string.Join("\n",lostManuals.Take(12).Select(m=>"- "+m.Code+" "+m.Description+" = "+(m.ManualInputText??Convert.ToString(m.ManualQuantity,CultureInfo.InvariantCulture))+" "+m.Unit))+(lostManuals.Count>12?"\n...":""):""),"BACKUP mapping",MessageBoxButtons.OK,MessageBoxIcon.Information);dashboardDirty=true;RefreshVisibleWorksViews();excelSaveTimer.Stop();excelSaveTimer.Start();}
 async void RefreshBackupBill(){try{Guard();Commit();if(worksExcel==null||!linkedHasBackup)throw new Exception("Link BACKUP first.");if(currentSync!=null)await currentSync;await LoadCatalogue();lastExcelXml="";ScheduleWorksExcel();}catch(Exception ex){ExcelCommandFailure(ex,"Refresh BACKUP items");}}
 void ScheduleWorksExcel(){excelCloseFlushed=false;quantityRevision++;syncPending=true;if(openingPow||worksExcel==null||linkingExcel||disconnectingExcel||syncingExcel||excelBroken||IsDisposed)return;worksExcelTimer.Stop();worksExcelTimer.Start();}
 Task SyncExcelAsync(bool force=false,bool map=false){if(openingPow||worksExcel==null||linkingExcel||excelBroken)return Task.FromResult(true);if(currentSync!=null&&!currentSync.IsCompleted){syncPending=true;return currentSync;}currentSync=RunExcelSync(force,map);return currentSync;}
 async Task RunExcelSync(bool force,bool mapping){syncingExcel=true;syncPending=false;long revision=quantityRevision;var link=worksExcel;try{if(childWorksDirty)Recalculate();var issues=WorksValidationIssues();string partial=issues.Count>0?"PARTIAL ("+issues.Count+" input issues listed in Bill of Quantities) | ":"";if(linkedHasBackup){var demands=BackupQuantities().Where(d=>issues.Count==0||d.ManualOverride||d.Quantity>1e-10||d.Sources.Any(source=>source.Quantity>1e-10)).ToList();string stamp=QuantityStamp(demands)+"\nISSUES:"+string.Join("\n",issues);if(!force&&stamp==lastExcelXml)return;if(mapping)PowTiming.Start("Mapping");var plan=await excelWorker.Run(()=>link.PrepareQuantityWrite(demands,mapping));if(IsDisposed)return;ApplyBoqRouteOverrides(plan);if(mapping){PowTiming.Mark("read BACKUP items");using(var dialog=new BackupMapDialog(plan.Demands,plan.Targets,plan.Routes))if(dialog.ShowDialog(this)!=DialogResult.OK){PowTiming.Finish();return;}PowTiming.Mark("mapping dialog (your time)");/* Show the chosen mapping in the app at once; the Excel write below can take a while. *//* the mapping dialog is authoritative: earlier BOQ overrides are replaced by its choices */boqRouteOverrides.Clear();boqUnmapped.Clear();foreach(var d in plan.Demands)if(!plan.Routes.ContainsKey(d.Key)){boqRouteOverrides[d.Key]=null;boqUnmapped.Add(d.Key);}foreach(var route in plan.Routes)backupBillRoutes[route.Key]=route.Value.SlotId;/* an app quantity mapped here to another item than its own pay item keeps that choice (and is written there) */foreach(var d in plan.Demands){BackupTarget chosen;if(d.ManualOverride||d.TargetSlotId==null||!plan.Routes.TryGetValue(d.Key,out chosen))continue;var own=BackupMapping.ResolveTarget(d,plan.Targets);if(own!=null&&own.SlotId==chosen.SlotId)continue;boqRouteOverrides[d.Key]=chosen.SlotId;d.TargetSlotId=null;d.TargetIdentity=null;}dashboardDirty=true;RefreshVisibleWorksViews();PowTiming.Mark("update BOQ in the app");excelStatus.Text=partial+"Mapping applied in the app. Writing quantities to Excel in the background…";}PowIssueOutput.ExcludeTargets(plan,backupBill.Where(b=>b.ManualInputText!=null&&!BackupBill.ReadQuantity(b.ManualInputText).HasValue).Select(b=>b.Slot));if(plan.Demands.Count==0){lastExcelXml=stamp;excelStatus.Text=partial+"BACKUP linked. No valid quantities to write; review input issues in Bill of Quantities.";excelSaveTimer.Stop();excelSaveTimer.Start();return;}bool preserve=issues.Count>0||!projectQuantitiesKnown;await excelWorker.Run(()=>{link.KeepUnloadedBackupItems=preserve;link.ClearMissingBackupItems=projectQuantitiesKnown;link.ApplyQuantityWrite(plan);});if(IsDisposed)return;if(mapping)PowTiming.Mark("write quantities to Excel");ApplyBackupWrite();if(mapping){RefreshVisibleWorksViews();PowTiming.Mark("refresh BOQ after Excel");ShowTiming(PowTiming.Finish());}lastExcelXml=stamp;/* Owner (18 November 2026, "ilipat sa status"): quantities that are not mapped are listed in the Bill of Quantities
   Status panel (double-click to map); the bottom bar only reports the Excel update. *//* typed BOQ quantities that could not be written are named (owner, 19 November 2026: "hindi pa din niya namamap sa BACKUP") */var notWritten=plan.Demands.Where(d=>d.ManualOverride&&d.ManualPriority==2&&!plan.Routes.ContainsKey(d.Key)).Select(d=>d.Description).ToList();var staleRows=link.StaleBackupRows.ToList();int cleared=link.ClearedBackupRows.Count;excelStatus.Text=partial+(cleared>0?cleared+" BACKUP quantit"+(cleared==1?"y":"ies")+" without a quantity in the app cleared | ":"")+(staleRows.Count>0?"old mapping names removed at BACKUP row(s) "+string.Join(", ",staleRows.Take(5))+(staleRows.Count>5?" ...":"")+" (map again if needed) | ":"")+(notWritten.Count>0?notWritten.Count+" typed quantit"+(notWritten.Count==1?"y":"ies")+" not written - their BACKUP item is not found once in the workbook (use Refresh BACKUP items): "+string.Join("; ",notWritten.Take(3))+(notWritten.Count>3?" ...":"")+" | ":"")+"Excel quantities updated | "+ExcelNotSaved+".";}else{var p=ProjectInfoStore.Read();var t=FinalQuantityTables();var b=BillOfQuantities();await excelWorker.Run(()=>link.UpdateWorksQuantities(t,b,p));excelStatus.Text=partial+"Excel quantities updated | "+ExcelNotSaved+".";}excelSaveTimer.Stop();excelSaveTimer.Start();}finally{syncingExcel=false;if(!IsDisposed&&!openingPow&&!excelBroken&&!disconnectingExcel&&(syncPending||quantityRevision!=revision)){worksExcelTimer.Stop();worksExcelTimer.Start();}}}
 static string QuantityStamp(IEnumerable<BackupDemand> demands){return string.Join("\n",demands.OrderBy(d=>d.Key,StringComparer.Ordinal).Select(d=>d.Key+"|"+d.Quantity.ToString("R",CultureInfo.InvariantCulture)+"|"+d.Unit+"|"+d.ManualOverride+"|"+d.ManualPriority+"|"+d.TargetSlotId+"|"+d.TargetIdentity));}
 internal const string ExcelNotSaved="not saved by the app - save the workbook in Excel (Ctrl+S)";
 async Task<bool> ExcelUnsaved(){if(worksExcel==null||excelBroken||excelWorker==null)return false;var link=worksExcel;try{return await excelWorker.Run(()=>link.HasUnsavedChanges);}catch(Exception){return false;}}
 /* reports (never saves) a workbook with changes that are not saved yet */
 async Task FlushExcelFile(){if(!await ExcelUnsaved()||IsDisposed||excelStatus==null||excelStatus.Text.Contains(ExcelNotSaved))return;excelStatus.Text=excelStatus.Text.TrimEnd('.',' ')+" | "+ExcelNotSaved+".";}
 async void SyncWorksExcel(){try{Guard();Commit();if(currentSync!=null)await currentSync;await SyncExcelAsync(true);await FlushExcelFile();}catch(Exception ex){ExcelCommandFailure(ex,"Sync to Excel");}}
 async void EditBackupMapping(){try{Guard();Commit();Recalculate();if(worksExcel==null||!linkedHasBackup)throw new Exception("Link BACKUP first.");/* a sync started by the timer in between would otherwise be returned instead of opening the mapping */while(currentSync!=null&&!currentSync.IsCompleted)await currentSync;if(excelBroken)throw new Exception("The link to the Excel workbook expired. Open / link the workbook again, then use Map BACKUP items.");if(linkingExcel||openingPow)throw new Exception("Excel is still being linked or the project is still opening. Try again in a moment.");worksExcelTimer.Stop();await SyncExcelAsync(true,true);await FlushExcelFile();}catch(Exception ex){ExcelCommandFailure(ex,"Map BACKUP items");}}
 async void DisconnectWorksExcel(){if(openingPow||disconnectingExcel)return;if(linkingExcel){excelStatus.Text="Excel is still linking; disconnect once linking finishes.";return;}if(worksExcel==null)return;disconnectingExcel=true;worksExcelTimer.Stop();excelSaveTimer.Stop();excelStatus.Text="Disconnecting Excel; writing the last quantities in the background.";/* owner (19 November 2026, "ayaw pa magdisconnect"): a failed last write no longer keeps the link; it is reported and Excel is disconnected */Exception lastWrite=null,failure=null;try{Commit();if(currentSync!=null)try{await currentSync;}catch(Exception ex){lastWrite=ex;}if(!excelBroken&&lastWrite==null){try{await SyncExcelAsync();}catch(Exception ex){lastWrite=ex;}}bool unsaved=await ExcelUnsaved();await DropExcel();syncPending=false;excelStatus.Text=(lastWrite!=null?"Excel disconnected; the last quantities were NOT written ("+(ExcelBusyFilter.IsBusy(lastWrite)?"Excel was busy":lastWrite.Message)+"). ":"")+(unsaved?"Excel disconnected. The workbook stays open in Excel with unsaved quantities - save it in Excel.":"Excel disconnected. Tool Kit quantities and workbook retained.");}catch(Exception ex){ExcelFailure(ex);failure=ex;}finally{disconnectingExcel=false;worksExcelTimer.Stop();excelSaveTimer.Stop();}if(failure!=null&&worksExcel!=null){try{await DropExcel();excelStatus.Text="Excel disconnected after an error: "+failure.Message;}catch(Exception){}}}
 async Task DropExcel(){var worker=excelWorker;var link=worksExcel;worksExcel=null;linkedHasBackup=false;excelBroken=false;UpdateExcelConnectionSummary();lastExcelXml="";if(worker!=null){if(link!=null)try{await worker.Run(()=>link.Dispose());}catch{}worker.Dispose();}excelWorker=null;}
 void DisposeExcelWorker(){excelSaveTimer.Dispose();var worker=excelWorker;var link=worksExcel;if(worker!=null){if(link!=null)worker.Run(()=>link.Dispose());worker.Dispose();}excelWorker=null;worksExcel=null;}
 void ExcelFailure(Exception error){bool stale=false;for(Exception e=error;e!=null;e=e.InnerException){var com=e as COMException;if(com!=null&&(com.ErrorCode==unchecked((int)0x80010114)||com.ErrorCode==unchecked((int)0x80010108)||com.ErrorCode==unchecked((int)0x800401FD)||com.ErrorCode==unchecked((int)0x800706BA)))stale=true;}if(stale){excelBroken=true;worksExcelTimer.Stop();excelSaveTimer.Stop();excelStatus.Text="Excel reference expired ("+error.Message+"). Quantities remain in Tool Kit. Use open workbook to reconnect.";}else excelStatus.Text="Excel sync paused: "+(ExcelBusyFilter.IsBusy(error)?ExcelBusyFilter.BusyMessage:error.Message);}
 /* a command the owner clicked also shows why it stopped (the status bar is easy to miss) */
 void ExcelCommandFailure(Exception error,string title){ExcelFailure(error);if(!IsDisposed)MessageBox.Show(this,ExcelBusyFilter.IsBusy(error)?ExcelBusyFilter.BusyMessage:error.Message,title,MessageBoxButtons.OK,MessageBoxIcon.Information);}
 async void FinishExcelClose(){try{PowTiming.Mark("before Excel");if(currentSync!=null)await currentSync;PowTiming.Mark("wait running Excel update");if(!excelBroken){await SyncExcelAsync(true);PowTiming.Mark("Excel quantities");string book=worksExcel==null?"":System.IO.Path.GetFileName(worksExcel.PathName);if(await ExcelUnsaved())MessageBox.Show(this,"The latest quantities are written in the open Excel workbook \""+book+"\", but the app does not save it.\n\nSave the workbook in Excel (Ctrl+S) before closing Excel.","Excel workbook not saved",MessageBoxButtons.OK,MessageBoxIcon.Information);}}catch(Exception ex){ExcelFailure(ex);MessageBox.Show(this,"Latest Excel quantities were not written: "+ex.Message+"\nSave Bill of Quantities to retain all inputs.","Excel quantities");}finally{closingExcel=false;excelCloseFlushed=true;if(!IsDisposed)Close();}}
